function fixGoogleTranslateInputs() {
		const inputs = [
			{ id: "goog-gt-votingInputSrcLang", label: "Source Language Input" },
			{ id: "goog-gt-votingInputTrgLang", label: "Target Language Input" },
			{ id: "goog-gt-votingInputSrcText", label: "Source Text Input" },
			{ id: "goog-gt-votingInputTrgText", label: "Target Text Input" },
			{ id: "goog-gt-votingInputVote", label: "Vote Input" },
		];

		let allLabelsSet = true;
		inputs.forEach((item) => {
			const input = document.getElementById(item.id);
			if (input) {
				input.setAttribute("aria-label", item.label);
			} else {
				allLabelsSet = false;
			}
		});

		if (allLabelsSet) {
			googleObserver.disconnect();
		}
	}
	const googleObserver = new MutationObserver((mutationsList, observer) => {
		for (let mutation of mutationsList) {
			if (mutation.type === "childList") {
				fixGoogleTranslateInputs();
			}
		}
	});
	googleObserver.observe(document.body, { childList: true, subtree: true });
 fixGoogleTranslateInputs();

