	var m = jobDetailsMap;
	var parsedOptions = cRecord.options || {};

	if (m.titleB) m.titleB.textContent = decodeHtmlEntities(cRecord.title || "");

	if (m.callouts) {
		m.callouts.innerHTML = "";
		if (Array.isArray(parsedOptions.attributes)) {
			parsedOptions.attributes.forEach(function(attr) {
				var header = attr.val_header || "";
				var text   = attr.val_text   || "";
				var icon   = parseIconClass(attr.val_icon) || { class: "bi bi-info-circle", ligature: "" };
				var wrap = document.createElement("div");
				wrap.innerHTML = `
					<p class="d-flex gap-3 align-items-center my-2 my-lg-3">
						<i class="${icon.class} flex-shrink-0 d-flex align-items-center justify-content-center text-primary bg-white rounded-circle w-h-48 fs-5">${icon.ligature}</i>
						<span><strong class="small text-muted lh-1">${header}</strong><br>${text}</span>
					</p>`;
				m.callouts.append(wrap.firstElementChild);
			});
		}

		var posted = cRecord.posted || "";
		if (posted) {
			var pWrap = document.createElement('div');
			pWrap.innerHTML = `
				<p class="d-flex gap-3 align-items-center">
					<i class="bi bi-clock flex-shrink-0 d-flex align-items-center justify-content-center text-primary bg-white rounded-circle w-h-48 fs-5"></i>
