				</p>`;
			m.callouts.append(pWrap.firstElementChild);
		}
	}

	if (m.apply) {
		var btnURL  = (parsedOptions.website_url || "").trim();
		var btnText = (parsedOptions.website_text || "Learn More").trim();

		if (btnURL && btnURL !== "#") {
			m.apply.classList.remove("d-none");
			m.apply.setAttribute("href", btnURL);
			m.apply.setAttribute("target", "_blank");
			m.apply.innerHTML = btnText + '<i class="bi bi-box-arrow-up-right ms-2"></i>';
		} else {
			m.apply.classList.add("d-none");
			m.apply.setAttribute("href", "#");
		}
	}

